{
  "kind": "ProjectBlueprint",
  "version": 1,
  "created_for_component": "project_generation",
  "customer_goal": "Build a tiny local notes CLI with README, tests, API evidence, and local model evidence",
  "selected_delivery_shape": "tiny_local_notes_cli",
  "scope_note": "This blueprint intentionally corrects execution toward the raw customer goal while retaining the acceptance requirement for honest degraded-mode local model reporting.",
  "owned_by_next_component": "runtime_execution",
  "product_summary": "A dependency-light Python CLI for managing local notes in a JSON store, with deterministic tests, README instructions, a public API evidence command using Open-Meteo sample data, and a local-model evidence command that reports configured, missing, or degraded model status honestly.",
  "non_goals": [
    "Cloud note synchronization",
    "Silent success when a local model is missing",
    "Binary assets committed as generated text",
    "Large GUI or video workbench implementation for this tiny CLI request"
  ],
  "runtime_constraints": {
    "language": "Python",
    "minimum_python": "3.10",
    "preferred_python_observed": "3.12",
    "network_required_for_core_notes": false,
    "network_optional_for_api_evidence": true,
    "external_model_required": false,
    "model_absence_behavior": "report degraded or missing_model, never claim local inference succeeded"
  },
  "file_plan": [
    {
      "path": "README.md",
      "owner_component": "runtime_execution",
      "purpose": "User instructions, feature list, example CLI session, test commands, API evidence description, local model evidence explanation."
    },
    {
      "path": "notes_cli/__init__.py",
      "owner_component": "runtime_execution",
      "purpose": "Package marker and version export."
    },
    {
      "path": "notes_cli/storage.py",
      "owner_component": "runtime_execution",
      "purpose": "Atomic JSON persistence for local notes with explicit schema."
    },
    {
      "path": "notes_cli/core.py",
      "owner_component": "runtime_execution",
      "purpose": "Shared note operations: add, list, show, search, delete, export."
    },
    {
      "path": "notes_cli/evidence.py",
      "owner_component": "runtime_execution",
      "purpose": "API evidence collection and local model capability evidence."
    },
    {
      "path": "notes_cli/cli.py",
      "owner_component": "runtime_execution",
      "purpose": "Argparse command line interface over the shared core."
    },
    {
      "path": "tests/test_notes_cli.py",
      "owner_component": "runtime_execution",
      "purpose": "Unit tests for note creation, listing, search, deletion, export, and honest local-model evidence."
    },
    {
      "path": "tests/test_api_evidence.py",
      "owner_component": "runtime_execution",
      "purpose": "Tests for deterministic API evidence parsing using bundled/sample JSON or mocked response."
    },
    {
      "path": "pyproject.toml",
      "owner_component": "runtime_execution",
      "purpose": "Project metadata, console script entry point, pytest configuration."
    },
    {
      "path": "TEST_PLAN.md",
      "owner_component": "runtime_execution",
      "purpose": "Manual and automated verification checklist."
    }
  ],
  "cli_contract": {
    "command": "notes",
    "environment": {
      "NOTES_STORE": "Optional path to the JSON note store. Defaults to .notes/data.json in the current project.",
      "LOCAL_NOTES_MODEL_CMD": "Optional shell command for local model probing or summarization evidence. If absent, model evidence must report missing_model/degraded."
    },
    "subcommands": [
      {
        "name": "add",
        "usage": "notes add --title TITLE --body BODY [--tag TAG ...]",
        "output": "JSON object containing created note id, title, tags, and created_at."
      },
      {
        "name": "list",
        "usage": "notes list [--json]",
        "output": "Human table by default or JSON list with --json."
      },
      {
        "name": "show",
        "usage": "notes show NOTE_ID",
        "output": "Single note as JSON or clear not-found error."
      },
      {
        "name": "search",
        "usage": "notes search QUERY [--json]",
        "output": "Matching notes where query appears in title, body, or tags."
      },
      {
        "name": "delete",
        "usage": "notes delete NOTE_ID",
        "output": "JSON deletion confirmation."
      },
      {
        "name": "export",
        "usage": "notes export --out PATH",
        "output": "Writes notes_export.json with schema and count."
      },
      {
        "name": "api-evidence",
        "usage": "notes api-evidence [--out evidence/api_evidence.json] [--offline-sample PATH]",
        "output": "JSON evidence record with source, request URL, response keys, sample value summary, and status online|offline_sample|error."
      },
      {
        "name": "model-evidence",
        "usage": "notes model-evidence [--out evidence/local_model_evidence.json]",
        "output": "JSON evidence record showing configured command, availability, status ok|missing_model|degraded|error, and no fake success."
      }
    ]
  },
  "data_contracts": {
    "note_store_schema": {
      "version": 1,
      "notes": [
        {
          "id": "string stable uuid or timestamp-safe id",
          "title": "string",
          "body": "string",
          "tags": ["string"],
          "created_at": "ISO-8601 UTC timestamp",
          "updated_at": "ISO-8601 UTC timestamp"
        }
      ]
    },
    "api_evidence_schema": {
      "status": "online|offline_sample|error",
      "source": "Open-Meteo",
      "url": "string",
      "created_at": "ISO-8601 UTC timestamp",
      "response_keys": ["string"],
      "sample": "object",
      "error": "string|null"
    },
    "local_model_evidence_schema": {
      "status": "ok|missing_model|degraded|error",
      "configured": "boolean",
      "command": "string|null",
      "created_at": "ISO-8601 UTC timestamp",
      "details": "string",
      "probe_output_preview": "string|null"
    }
  },
  "acceptance_checks_for_runtime_execution": [
    "Core note commands work without network access.",
    "Tests run with python -m pytest and do not require a real local model.",
    "api-evidence can operate from an offline sample or mocked response and records Open-Meteo source metadata.",
    "model-evidence reports missing_model when LOCAL_NOTES_MODEL_CMD is not set.",
    "README includes install, usage, tests, API evidence, and local model evidence sections.",
    "No command claims local model success unless a configured local command actually executes successfully."
  ]
}
